function [d] = drivers_for(model)
%DRIVERS_FOR  data.drivers: the index set a density model takes.
%   model: AtmosModel (passed a choice, as its option's number)
%   returns d: DriverSet (passed a choice, as its option's number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    d = 0;
    if (model == 0)
        d = 0;
    elseif ((model == 1) || (model == 3))
        d = 1;
    elseif (model == 4)
        d = 2;
    else
        d = 3;
    end
end
